    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker = max((v for v in counts if v != background), key=lambda v: counts[v])
    out = [row[:] for row in grid]
    # The marker locations indicate where to place copies of the motif.
    # The motif is 4,0,4 vertically, centered on each marker.
    motif = [4, 0, 4]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for i, value in enumerate(motif):
                    rr = r + i - 1
                    if 0 <= rr < h:
